using System;using System.IO;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;namespace RockPro{public static class LatchInProcess{public static int Run(string folder){var j=new JavaScriptSerializer();var r=(System.Collections.Generic.Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));dynamic l=Marshal.GetActiveObject("IronCAD.Application");var a=(IZBaseApp)l.ZIronCADApp;var d=a.ActiveDoc;if(d.Name!=(string)r["output"])throw new Exception("Wrong document");if(d.Modified)throw new Exception("Unsaved edits");d.Close2(true);bool already;var n=a.OpenFile2((string)r["output"],false,true,out already);a.ActiveDoc=n;((IZSceneDoc)n).Redraw();File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(new{passed=!already,document=n.Name}));return already?1:0;}}}
